import Model from 'flarum/common/Model';
export default class Question extends Model {
  question = (() => Model.attribute('question'))();
  answer = (() => Model.attribute('answer'))();
  groupId = (() => Model.attribute('groupId'))();
  maxUses = (() => Model.attribute('maxUses'))();
  activates = (() => Model.attribute('activates'))();
  uses = (() => Model.attribute('uses'))();
  group = (() => Model.hasOne('group'))();
  createdBy = (() => Model.hasOne('createdBy'))();
}
flarum.reg.add('stezkoy-doorquest', 'common/models/Question', Question);